impl self::TelegramMethod for SendVideo {
    type Method = Self;
    type Return = crate::types::Message;

    fn build_request<Client>(mut self, _bot: &Bot<Client>) -> self::Request<Self::Method> {
        let mut files = vec![];
        self::prepare_file(&mut files, &mut self.video);
        if let Some(file) = &mut self.thumbnail {
            self::prepare_file(&mut files, file);
        }
        if let Some(file) = &mut self.cover {
            self::prepare_file(&mut files, file);
        }
        self::Request::new("sendVideo", self, Some(files))
    }
}
