impl self::TelegramMethod for SendPoll {
    type Method = Self;
    type Return = crate::types::Message;

    fn build_request<Client>(mut self, _bot: &Bot<Client>) -> self::Request<Self::Method> {
        let mut files = vec![];
        self::prepare_input_poll_options(&mut files, self.options.iter_mut().collect());
        if let Some(media) = &mut self.explanation_media {
            self::prepare_input_poll_media(&mut files, media);
        }
        if let Some(media) = &mut self.media {
            self::prepare_input_poll_media(&mut files, media);
        }
        self::Request::new("sendPoll", self, Some(files))
    }
}
